 shell/autotests/CMakeLists.txt                |  1 +
 shell/shellcorona.cpp                         | 22 +++++++++++++++++++
 shell/shellcorona.h                           |  3 +++
 4 files changed, 27 insertions(+)

diff --git a/kcms/region_language/regionandlangsettingsbase.kcfgc b/kcms/region_language/regionandlangsettingsbase.kcfgc
index 94f9d1aa6d..013d3747eb 100644
--- a/kcms/region_language/regionandlangsettingsbase.kcfgc
+++ b/kcms/region_language/regionandlangsettingsbase.kcfgc
@@ -4,3 +4,4 @@ Mutators=true
 DefaultValueGetters=true
