 }

 void ShellCorona::init()
@@ -1839,6 +1841,26 @@ void ShellCorona::setupLookAndFeel()
     });
 }

+void ShellCorona::setupLanguageWatcher()
+{
+    m_localeConfigWatcher = KConfigWatcher::create(KSharedConfig::openConfig(u"plasma-localerc"_s));
+    connect(m_localeConfigWatcher.data(), &KConfigWatcher::configChanged, this, [](const KConfigGroup &group, const QByteArrayList &names) {
+        if (group.name() != "Translations"_L1 || !names.contains(QByteArrayLiteral("LANGUAGE"))) {
+            return;
+        }
+        const QString language = group.readEntry("LANGUAGE", QString());
+        if (language == qEnvironmentVariable("LANGUAGE")) {
+            return;
+        }
+        qputenv("LANGUAGE", language.toUtf8());
+        QProcessEnvironment environment;
+        environment.insert(u"LANGUAGE"_s, language);
+        new KUpdateLaunchEnvironmentJob(environment);
+        QEvent event(QEvent::LanguageChange);
+        QCoreApplication::sendEvent(QCoreApplication::instance(), &event);
+    });
+}
+
 void ShellCorona::handleColorRequestedFromDBus(const QDBusMessage &msg)
 {
